{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Testosterone undecanoate, a long-chain fatty acid ester prodrug with high lipophilicity, has an absolute oral bioavailability of only 6.8% in humans, supporting low F for the similarly lipophilic long-chain ester/lactone query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Dimethandrolone undecanoate, another long-chain undecanoate ester, shows poor and inconsistent oral bioavailability in men, supporting low F for the query's long alkyl ester motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Perindopril, an ester prodrug, has a mean oral bioavailability of 19% ± 7% in healthy subjects, below the 20% threshold, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Pravastatin has an absolute oral bioavailability of 17% in humans, below the 20% threshold, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Eliglustat has a simulated absolute oral bioavailability of 8.6%, supporting low F, though this is a PBPK simulation rather than a direct clinical measurement.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Laninamivir octanoate, a long-chain ester prodrug, has only 15% oral bioavailability in humans, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Cytarabine ocfosfate, a lipophilic prodrug, has a systemic/metabolic bioavailability of 15.8% in patients, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Hexarelin has an oral bioavailability of 0.3% in humans, supporting low F, despite being a peptide with limited structural similarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "DVAS, a dodecyl ester dipeptide, showed an average oral bioavailability of 60% in healthy volunteers, which would support high F, but its low transferability (0.398) and structural differences limit its relevance.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a highly lipophilic N-formyl-leucine ester of a beta-lactone with long alkyl chains, designed for local GI action and known to have negligible systemic absorption. The strongest transferable evidence—long-chain fatty acid ester prodrugs such as testosterone undecanoate (6.8% F) and dimethandrolone undecanoate (poor F)—plus multiple other drugs with F below 20% (pravastatin 17%, perindopril 19%, eliglustat 8.6%, laninamivir octanoate 15%, cytarabine ocfosfate 15.8%, hexarelin 0.3%) overwhelmingly support F < 20%. The single high-F analogue (DVAS, 60%) has low transferability and does not outweigh the consistent low-F pattern.",
  "evidence_gaps": [
    "No direct orlistat oral bioavailability measurement is included in the provided evidence.",
    "Most analogues are not beta-lactone lipase inhibitors; class-specific absorption mechanisms may differ.",
    "Some records are PBPK simulations or unspecified bioavailability types rather than direct absolute human F measurements.",
    "Several analogues are near the 20% threshold, but the query's expected F is far lower."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

